            return False
        idx = 1
        total = 0
        for _ in range(t):
            n = int(tok[idx]); k = int(tok[idx + 1]); s = tok[idx + 2]
            idx += 3
            if not (1 <= k <= n <= 2 * 10**5):
                return False
            if len(s) != n or any(c not in "BW" for c in s):
                return False
            total += n
        if total > 2 * 10**5:
