        return idx == len(tok)
    except Exception:
        return False

def _solve_one(n, k, s):
    start = 0
    for i, c in enumerate(s):
        if c == 'B':
            start |= (1 << i)
    if start == 0:
        return 0
    ops = [((1 << k) - 1) << i for i in range(n - k + 1)]
    dist = {start: 0}
    q = deque([start])
    while q:
        m = q.popleft()
        if m == 0:
            return dist[m]
        for op in ops:
            nm = m & ~op
            if nm not in dist:
                dist[nm] = dist[m] + 1
                q.append(nm)
    return dist[0]

