    elif mode == 1:
        nums = draw(st.lists(pool, min_size=n, max_size=n, unique=True))
    else:
        nums = draw(st.lists(st.integers(1, 10**9), min_size=n, max_size=n, unique=True))
    return json.dumps(nums)

